import { describe, it, expect } from 'vitest';
import React from 'react';
import ReactThreeTestRenderer from '@react-three/test-renderer';
import * as THREE from 'three';
import Gear from '../src/Gear.jsx';

const EPS = 1e-6;

async function getToothMeshes(root) {
  // Traverse the mounted scene graph for meshes named "tooth-*".
  const found = [];
  root.scene.traverse((obj) => {
    if (obj.isMesh && /^tooth-/.test(obj.name ?? '')) found.push(obj);
  });
  return found;
}

describe('Gear', () => {
  it('renders 8 teeth at radius 2 within 1e-6', async () => {
    const renderer = await ReactThreeTestRenderer.create(
      <Gear teeth={8} radius={2} spinSpeed={Math.PI} />
    );

    const teeth = await getToothMeshes(renderer);
    expect(teeth).toHaveLength(8);

    for (let i = 0; i < 8; i++) {
      const mesh = renderer.scene.getObjectByName(`tooth-${i}`);
      expect(mesh).toBeTruthy();
      const angle = (i / 8) * Math.PI * 2;
      expect(mesh.position.x).toBeCloseTo(Math.cos(angle) * 2, 10);
      expect(mesh.position.y).toBeCloseTo(Math.sin(angle) * 2, 10);
      expect(mesh.position.z).toBe(0);

      const distFromAxis = Math.hypot(mesh.position.x, mesh.position.y);
      expect(Math.abs(distFromAxis - 2)).toBeLessThanOrEqual(EPS);
    }

    // Hub exists too
    expect(renderer.scene.getObjectByName('hub')).toBeTruthy();
  });

  it('advances rotation.z by ~PI after 60 frames of 1/60s', async () => {
    const renderer = await ReactThreeTestRenderer.create(
      <Gear teeth={8} radius={2} spinSpeed={Math.PI} />
    );

    await renderer.advanceFrames(60, 1 / 60);

    const group = renderer.scene.children[0];
    expect(group).toBeTruthy();
    const advanced = group.rotation.z;
    expect(Math.abs(advanced - Math.PI)).toBeLessThanOrEqual(5e-2);
  });

  it('rerenders to 12 teeth when teeth prop changes', async () => {
    const renderer = await ReactThreeTestRenderer.create(
      <Gear teeth={8} radius={2} spinSpeed={Math.PI} />
    );
    expect(await getToothMeshes(renderer)).toHaveLength(8);

    await renderer.update(<Gear teeth={12} radius={2} spinSpeed={Math.PI} />);

    const teeth = await getToothMeshes(renderer);
    expect(teeth).toHaveLength(12);
    for (let i = 0; i < 12; i++) {
      const mesh = renderer.scene.getObjectByName(`tooth-${i}`);
      expect(mesh).toBeTruthy();
      const angle = (i / 12) * Math.PI * 2;
      const dist = Math.hypot(mesh.position.x, mesh.position.y);
      expect(dist).toBeCloseTo(2, 10);
      expect(mesh.position.x).toBeCloseTo(Math.cos(angle) * 2, 10);
      expect(mesh.position.y).toBeCloseTo(Math.sin(angle) * 2, 10);
    }
  });
});

