import React, { useRef } from 'react';
import { useFrame } from '@react-three/fiber';

/**
 * <Gear teeth={n} radius={r} spinSpeed={s} />
 *
 * Renders a group containing:
 *  - a cylinder hub mesh named "hub"
 *  - n box tooth meshes named "tooth-<i>" positioned around the
 *    circumference at distance `radius` from the hub axis (z axis).
 * Each frame the group's rotation.z advances by spinSpeed * delta.
 */
export default function Gear({ teeth = 8, radius = 1, spinSpeed = 0 }) {
  const groupRef = useRef();

  useFrame((state, delta) => {
    if (groupRef.current) {
      groupRef.current.rotation.z += spinSpeed * delta;
    }
  });

  const toothAngles = Array.from({ length: teeth }, (_, i) => (i / teeth) * Math.PI * 2);

  return (
    <group ref={groupRef}>
      {/* Cylinder hub on the z axis */}
      <mesh name="hub">
        <cylinderGeometry args={[radius * 0.5, radius * 0.5, 0.4, 32]} />
        <meshStandardMaterial color="#888888" />
      </mesh>

      {/* Teeth around the circumference */}
      {toothAngles.map((angle, i) => (
        <mesh
          key={i}
          name={`tooth-${i}`}
          position={[Math.cos(angle) * radius, Math.sin(angle) * radius, 0]}
          rotation={[0, 0, angle]}
        >
          <boxGeometry args={[0.6, 0.3, 0.4]} />
          <meshStandardMaterial color="#cccccc" />
        </mesh>
      ))}
    </group>
  );
}

